<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/business_helpers.php';require_login();$id=(int)($_GET['id']??0);$error='';
$st=$conn->prepare('SELECT s.*,c.car_name,c.plate_number FROM car_sales s JOIN cars c ON c.id=s.car_id WHERE s.id=?');$st->bind_param('i',$id);$st->execute();$sale=$st->get_result()->fetch_assoc();if(!$sale){set_flash('error','Sale not found.');redirect_to('backend/sales/index.php');}$paid=sale_paid_total($conn,$id);$balance=max(0,(float)$sale['sale_price']-$paid);
if($_SERVER['REQUEST_METHOD']==='POST'){$amount=(float)($_POST['amount']??0);$date=$_POST['payment_date']??'';$method=trim($_POST['method']??'');$ref=trim($_POST['reference_number']??'');$notes=trim($_POST['notes']??'');$uid=(int)$_SESSION['user_id'];if($amount<=0||$date===''||$amount>$balance+0.01){$error='Enter a valid payment amount not greater than the outstanding balance.';}else{$st=$conn->prepare('INSERT INTO sale_payments(sale_id,amount,payment_date,method,reference_number,notes,received_by) VALUES(?,?,?,?,?,?,?)');$st->bind_param('idssssi',$id,$amount,$date,$method,$ref,$notes,$uid);if($st->execute()){sync_sale_payment_status($conn,$id);car_sales_audit($conn,'PAYMENT','sale',$id,'Recorded customer payment of '.money($amount).'.',null,['amount'=>$amount,'date'=>$date,'method'=>$method,'reference'=>$ref]);set_flash('success','Payment recorded successfully.');redirect_to('backend/sales/receipt.php?id='.$id);}else{$error='Could not record payment.';}}}
$page_title='Add Payment';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><h1 class="page-title">Add Sale Payment</h1><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))"><div class="card"><h2>Sale</h2><p><strong>Car:</strong> <?=e($sale['car_name'].' / '.car_sales_plate_label($sale['plate_number']))?></p><p><strong>Buyer:</strong> <?=e($sale['buyer_name'])?></p><p><strong>Sale Price:</strong> <?=money($sale['sale_price'])?></p><p><strong>Paid:</strong> <?=money($paid)?></p><p><strong>Outstanding:</strong> <?=money($balance)?></p></div><div class="card form-card"><?php if($error):?><div class="flash-message error" style="position:static"><?=e($error)?></div><?php endif;?><form method="post"><div class="form-group"><label>Amount *</label><input type="number" step="0.01" min="0.01" max="<?=$balance?>" name="amount" required></div><div class="form-group"><label>Payment Date *</label><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required></div><div class="form-group"><label>Method</label><select name="method"><option>Cash</option><option>Bank Transfer</option><option>Mobile Money</option><option>Cheque</option><option>Other</option></select></div><div class="form-group"><label>Reference Number</label><input name="reference_number"></div><div class="form-group"><label>Notes</label><textarea name="notes" rows="2"></textarea></div><button class="btn btn-green">Save Payment</button><a class="btn btn-dark" href="index.php">Cancel</a></form></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
